-- Native records required by audit/retention/erasure. These use the current installation's database-byte attachments.
CREATE TABLE peg_proofs (id TEXT PRIMARY KEY,task_id TEXT NOT NULL,current_version TEXT,created_by TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE peg_proof_versions (id TEXT PRIMARY KEY,proof_id TEXT NOT NULL,attachment_id TEXT NOT NULL UNIQUE,version INTEGER NOT NULL,digest TEXT NOT NULL,created_by TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(proof_id,version));
CREATE TABLE peg_proof_decisions (id TEXT PRIMARY KEY,proof_id TEXT NOT NULL,version_id TEXT NOT NULL,actor_id TEXT NOT NULL,action TEXT NOT NULL CHECK(action IN ('approve','changes','reject')),at INTEGER NOT NULL,reason TEXT NOT NULL);
CREATE TABLE peg_data_erasing_proofs (proof_id TEXT PRIMARY KEY);
CREATE TRIGGER peg_proof_versions_immutable BEFORE UPDATE ON peg_proof_versions BEGIN SELECT RAISE(ABORT,'immutable_proof_version'); END;
CREATE TRIGGER peg_proof_versions_delete BEFORE DELETE ON peg_proof_versions WHEN NOT EXISTS(SELECT 1 FROM peg_data_erasing_proofs WHERE proof_id=OLD.proof_id) BEGIN SELECT RAISE(ABORT,'reviewed_proof_erasure_required'); END;
CREATE TRIGGER peg_proof_decisions_immutable BEFORE UPDATE ON peg_proof_decisions BEGIN SELECT RAISE(ABORT,'immutable_proof_decision'); END;
CREATE TRIGGER peg_proof_decisions_delete BEFORE DELETE ON peg_proof_decisions WHEN NOT EXISTS(SELECT 1 FROM peg_data_erasing_proofs WHERE proof_id=OLD.proof_id) BEGIN SELECT RAISE(ABORT,'reviewed_proof_erasure_required'); END;
CREATE TABLE peg_agent_outputs (id TEXT PRIMARY KEY,task_id TEXT NOT NULL,project_id TEXT NOT NULL,actor_id TEXT NOT NULL,processor TEXT NOT NULL,body TEXT NOT NULL,policy TEXT NOT NULL,operation_key TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(actor_id,operation_key));
CREATE TABLE peg_agent_retrieval (output_id TEXT PRIMARY KEY,task_id TEXT NOT NULL,body TEXT NOT NULL);
CREATE TABLE peg_search_records (task_id TEXT PRIMARY KEY,body TEXT NOT NULL);
INSERT INTO peg_search_records SELECT id,title||char(10)||description FROM peg_tasks;
CREATE TRIGGER peg_search_insert AFTER INSERT ON peg_tasks BEGIN INSERT INTO peg_search_records VALUES(NEW.id,NEW.title||char(10)||NEW.description); END;
CREATE TRIGGER peg_search_update AFTER UPDATE OF title,description ON peg_tasks BEGIN UPDATE peg_search_records SET body=NEW.title||char(10)||NEW.description WHERE task_id=NEW.id; END;
CREATE TRIGGER peg_search_delete AFTER DELETE ON peg_tasks BEGIN DELETE FROM peg_search_records WHERE task_id=OLD.id; END;
