CREATE TRIGGER peg_record_erasure_peg_proofs_insert BEFORE INSERT ON peg_proofs WHEN EXISTS(SELECT 1 FROM peg_data_erased_objects WHERE object_type='task' AND object_id=NEW.task_id) BEGIN SELECT RAISE(ABORT,'erased_object'); END;
CREATE TRIGGER peg_record_erasure_peg_proofs_update BEFORE UPDATE ON peg_proofs WHEN EXISTS(SELECT 1 FROM peg_data_erased_objects WHERE object_type='task' AND object_id=NEW.task_id) BEGIN SELECT RAISE(ABORT,'erased_object'); END;
